INSERT INTO `page_list` (`id`, `alias`, `page_title`, `page_content`, `status`) VALUES
(1, 'glowna', 'Strona główna', '<div class=\"wyszukiwarka-kontener\">\r\n    <label for=\"wyszukiwarka-produktow\">Szukaj produktu:</label>\r\n    <input type=\"search\" id=\"wyszukiwarka-produktow\" placeholder=\"Wpisz nazwę...\">\r\n    <div aria-live=\"polite\" id=\"obszar-statusu\">\r\n        <p id=\"licznik-wynikow\">Znaleziono produktów: 3</p>\r\n        <p id=\"brak-wynikow\" hidden>Brak produktów spełniających kryteria wyszukiwania.</p>\r\n    </div>\r\n</div>\r\n        <h2>Katalog produktów</h2>\r\n        <div class=\"katalog-grid\">\r\n            <article class=\"karta-produktu\">\r\n                <a href=\"index.php?idp=produkt\">\r\n                    <img src=\"img/ball.png\" alt=\"Piłka do piłki nożnej\" width=\"256\" height=\"256\">\r\n                    <h3>Piłka do piłki nożnej</h3>\r\n                    <p>Piłka czarno-biała do piłki nożnej</p>\r\n                    <p class=\"cena\">19.99zł</p>\r\n                </a>\r\n            </article>\r\n\r\n            <article class=\"karta-produktu\">\r\n            <img src=\"img/tennis.png\" alt=\"Piłka tenisowa\" width=\"256\" height=\"256\">\r\n            <h3>Piłka do tenisa</h3>\r\n            <p>Żółta piłka do tenisa ziemnego</p>\r\n            <p class=\"cena\">9.99zł</p>\r\n            </article>\r\n\r\n            <article class=\"karta-produktu\">\r\n                <img src=\"img/baseball.png\" alt=\"Piłka do kosza\" width=\"256\" height=\"256\">\r\n                <h3>Piłka do baseballa</h3>\r\n                <p>Biała piłka do baseballa</p>\r\n                <p class=\"cena\">24.99zł</p>\r\n            </article>\r\n        </div>\r\n        <section id=\"demo-jquery\">\r\n        <h2>Demonstracja Animacji jQuery</h2>\r\n        \r\n        <div class=\"kontener-animacji\">\r\n            <button type=\"button\" id=\"anim-a\" class=\"przycisk-anim\" aria-pressed=\"false\">Animacja A</button>\r\n            <button type=\"button\" id=\"anim-b\" class=\"przycisk-anim\">Animacja B</button>\r\n            <button type=\"button\" id=\"anim-c\" class=\"przycisk-anim\">Animacja C</button>\r\n        </div>\r\n\r\n        <div style=\"margin-top: 15px;\">\r\n            <span role=\"status\" id=\"status-anim-c\">Kroków: 0</span>\r\n        </div>\r\n\r\n        <div style=\"margin-top: 20px;\">\r\n            <button type=\"button\" id=\"btn-reset\">Resetuj A i C</button>\r\n        </div>\r\n\r\n        <div class=\"ajax\">\r\n            <h3>Test komunikacji z serwerem</h3>\r\n            <button type=\"button\" id=\"btn-ajax\">Sprawdź serwer</button>\r\n            <div role=\"status\" id=\"status-ajax\" style=\"margin-top: 10px; min-height: 20px;\">\r\n            </div>\r\n        </div>\r\n    </section>', 1),
(2, 'produkt', 'Produkt', '\r\n        <h2>Piłka do piłki nożnej</h2>\r\n        <img src=\"img/ball.png\" alt=\"piłka do piłki nożnej\" width=\"256\" height=\"256\">\r\n        <p class=\"cena\">19.99zł</p>\r\n        <p>\r\n            <strong>Piękna</strong> biało-czarna piłka do piłki nożnej.\r\n            <em>Wytrzyma</em> każdy celny i niecelny strzał na bramkę.\r\n        </p>\r\n        <h2>Cechy produktu</h2>\r\n        <ul>\r\n            <li>Lekka</li>\r\n            <li>Wytrzymała</li>\r\n            <li>Bezpieczna dla dzieci</li>\r\n        </ul>\r\n        <table>\r\n            <caption>Parametry techniczne</caption>\r\n            <thead>\r\n                <tr>\r\n                    <th scope=\"col\">Parametr</th>\r\n                    <th scope=\"col\">Wartość</th>\r\n                </tr>\r\n            </thead>\r\n            <tbody>\r\n                <tr>\r\n                    <td>Waga</td>\r\n                    <td>420g</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Materiał</td>\r\n                    <td>Poliuretan</td>\r\n                </tr>\r\n                <tr>\r\n                    <td>Średnica</td>\r\n                    <td>70cm</td>\r\n                </tr>\r\n            </tbody>\r\n        </table>\r\n        <p>\r\n            <a href=\"index.php?idp=kontakt\">Zapytaj o produkt</a>\r\n        </p>\r\n\r\n    ', 1),
(3, 'kontakt', 'Kontakt', '\r\n    <p>Podgląd lokalny. Formularz nie wysyła wiadomości.</p>\r\n    \r\n    <form id=\"formularz-kontaktowy\" method=\"get\" action=\"index.php?idp=kontakt\">\r\n        <div>\r\n            <label for=\"pole-email\">Twój adres e-mail (wymagane):</label>\r\n            <input type=\"email\" id=\"pole-email\" name=\"email\" required>\r\n        </div>\r\n        <div>\r\n            <label for=\"pole-produkt\">Wybierz produkt (wymagane):</label>\r\n            <select id=\"pole-produkt\" name=\"produkt\" required>\r\n                <option value=\"\">Wybierz produkt</option>\r\n                <option value=\"1\">Piłka do piłki nożnej</option>\r\n                <option value=\"2\">Piłka do baseballa</option>\r\n                <option value=\"3\">Piłka do tenisa ziemnego</option>\r\n            </select>\r\n        </div>\r\n        <div>\r\n            <label for=\"pole-ilosc\">Liczba sztuk (1-5, wymagane):</label>\r\n            <input type=\"number\" id=\"pole-ilosc\" name=\"ilosc\" required min=\"1\" max=\"5\" step=\"1\">\r\n        </div>\r\n\r\n        <p id=\"cena-podglad\" style=\"font-weight: bold; margin: 5px 0;\">Wybierz produkt i ilość, aby zobaczyć cenę.</p>\r\n\r\n        <div>\r\n            <label for=\"pole-wiadomosc\">Treść wiadomości (10-500 znaków, wymagane):</label>\r\n            <textarea id=\"pole-wiadomosc\" name=\"wiadomosc\" required minlength=\"10\" maxlength=\"500\"></textarea>\r\n            <p id=\"blad-wiadomosci\" hidden style=\"color: #FF0000; text-shadow: 0 0 10px #FF0000, 0 0 20px #FF3333; margin: 0;\">Wiadomość musi mieć minimum 10 znaków.</p>\r\n        </div>\r\n        <div>\r\n            <button type=\"submit\">Sprawdź zapytanie</button>\r\n        </div>\r\n    </form>\r\n\r\n    <div id=\"podsumowanie-wysylki\" hidden style=\"margin-top: 20px; padding: 10px; border: 1px solid var(--kolor-ramki);\">\r\n        <h3>Podsumowanie zapytania</h3>\r\n        <p id=\"podsumowanie-dane\"></p>\r\n        <p id=\"podsumowanie-wiadomosc\"></p>\r\n    </div>\r\n\r\n    ', 1),
(4, 'filmy', 'Filmy', '<section>\r\n<h2>Filmy</h2>\r\n<article class=\"film-pozycja\">\r\n    <h3>EL ACABADO FUNK - MRR</h3>\r\n    <iframe\r\n    src=\"https://www.youtube.com/embed/ukIM4IGGHHA?autoplay=0\"\r\n    title=\"EL ACABADO FUNK - MRR Piosenka\"\r\n    allowfullscreen></iframe>\r\n    <p><a href=\"https://youtu.be/ukIM4IGGHHA?si=L9s0IRoRUZglRVnF\">Sprawdź piosenkę na Youtube</a></p>\r\n</article>\r\n<article class=\"film-pozycja\">\r\n    <h3>Shakira - Waka Waka (This Time for Africa) (The Official 2010 FIFA World Cup™ Song)</h3>\r\n    <iframe\r\n    src=\"https://www.youtube.com/embed/pRpeEdMmmQ0?autoplay=0\"\r\n    title=\"Shakira - Waka Waka (This Time for Africa) (The Official 2010 FIFA World Cup™ Song)\"\r\n    allowfullscreen></iframe>\r\n    <p><a href=\"https://youtu.be/pRpeEdMmmQ0?si=h7EyphK7Dy2d5u5s\">Sprawdź piosenkę na Youtube</a></p>\r\n</article>\r\n<article class=\"film-pozycja\">\r\n    <h3>K\'NAAN - Wavin\' Flag (Coca-Cola Celebration Mix)</h3>\r\n    <iframe\r\n    src=\"https://www.youtube.com/embed/WTJSt4wP2ME?autoplay=0\"\r\n    title=\"K\'NAAN - Wavin\' Flag (Coca-Cola Celebration Mix)\"\r\n    allowfullscreen></iframe>\r\n    <p><a href=\"https://youtu.be/WTJSt4wP2ME?si=XYqkaP4KoJhTmJIA\">Sprawdź piosenkę na Youtube</a></p>\r\n</article>\r\n</section>', 1),
(5, 'szkic', 'Szkic', '<section><h2>Szkic sklepu (wersja robocza)</h2><p>Treść jest w trakcie opracowywania.</p></section>', 0);
